#include <iostream>
#include <string>
#include <vector>
#include <sstream>

int main() {
    int num;
    std::cin >> num;
    std::string strInput;
    std::cin >> strInput;

    std::string workingStr = strInput;
    std::string brackets = "_";
    int startPos = -1;
    int totalLen = workingStr.length();

    for (int idx = 0; idx < totalLen; idx++) {
        char ch = workingStr[idx];
        if (ch == '(') {
            startPos = idx;
        } else if (ch == ')') {
            brackets += workingStr.substr(startPos + 1, idx - startPos - 1) + "_";
            workingStr = workingStr.substr(0, startPos) + "_" + workingStr.substr(idx + 1);
            totalLen = workingStr.length();
            idx = startPos - 1;
            startPos = -1;
        }
    }

    // Split brackets string by '_'
    std::vector<std::string> bracketParts;
    std::stringstream ssBrackets(brackets);
    std::string token;
    while (std::getline(ssBrackets, token, '_')) {
        if (!token.empty()) {
            bracketParts.push_back(token);
        }
    }

    int bracketCount = static_cast<int>(bracketParts.size());

    // Split workingStr by '_'
    std::vector<std::string> segments;
    std::stringstream ssWorking(workingStr);
    while (std::getline(ssWorking, token, '_')) {
        segments.push_back(token);
    }

    int maxLen = 0;
    for (const auto& segment : segments) {
        if (segment.length() > maxLen) {
            maxLen = segment.length();
        }
    }

    std::cout << maxLen << " " << bracketCount << std::endl;

    return 0;
}
